           {:ok, pos3, ref3, cap2} <- parse_expr__106(stream, pos2, ref2, context),
           {:ok, pos4, ref4, cap3} <- parse_expr__107(stream, pos3, ref3, context),
           {:ok, pos5, ref5, cap4} <- parse_expr__109(stream, pos4, ref4, context) do
